using System;using System.IO;using System.Text;using UnityEngine;
public static class ClientFixture {
 public static string Run(){if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"run-final.txt"))){new GameObject("BatchTwoFinal").AddComponent<BatchTwoFinalClientFixture>();return "Started final visual checks";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"run-interactions.txt"))){new GameObject("BatchTwoInteractions").AddComponent<BatchTwoInteractionFixture>();return "Started native interactions";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"run-gardens.txt"))){new ConsoleCmdPantry().Execute(new System.Collections.Generic.List<string>{"build"},default(CommandSenderInfo));return "Garden authoring completed; inspect native log";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"quit-test.txt"))){Application.Quit();return "Quit isolated client";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"run-prefabs.txt"))){new ConsoleCmdBatchTwoPrefabs().Execute(new System.Collections.Generic.List<string>(),default(CommandSenderInfo));return "Prefab authoring completed: inspect report and missing-containers.txt";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"run-ui.txt"))){new GameObject("BatchTwoUI").AddComponent<BatchTwoUIFixture>();return "Started native UI fixture";}var s=new StringBuilder();var p=GameManager.Instance.World.GetPrimaryPlayer();
  foreach(var id in new[]{"wayrestWelcome","wayrestIncursions","wayrestRefuge","delveTraining"}){var d=Dialog.DialogList["delveWayrest"];var r=d.GetResponse(id);s.AppendLine("DIALOG "+id+" target="+(r==null?"NULL":r.NextStatementID));if(r!=null){d.SelectResponse(r,p);s.AppendLine("REPLY "+(d.CurrentStatement==null?"NULL":d.CurrentStatement.ID+" text="+d.CurrentStatement.Text));}}
  foreach(string path in new[]{"@:Entities/Vehicles/Car/car_black_dmg0Prefab.prefab","#@modfolder(ZZZDelveBatch01):Resources/batchone.unity3d?delveWagon0","#@modfolder(ZDelvePresentation):Resources/forestprops.unity3d?plantedDelveYarrow3Harvest"}){var g=DataLoader.LoadAsset<GameObject>(path,true);s.AppendLine("MODEL "+path);if(g==null){s.AppendLine("NULL");continue;}foreach(var t in g.GetComponentsInChildren<Transform>(true)){var c=t.GetComponent<Collider>();if(c!=null)s.AppendLine("COLLIDER "+t.name+" parent="+(t.parent==null?"ROOT":t.parent.name)+" layer="+t.gameObject.layer+" tag="+t.tag+" trigger="+c.isTrigger+" type="+c.GetType().Name);}}
  foreach(string name in new[]{"meleeWpnBladeT0BoneKnife","delveBoneDagger"}){var item=ItemClass.GetItem(name,false);var path=item.ItemClass.GetMeshfilePath((BlockShape.MeshPurpose)2,item);s.AppendLine("ITEM "+name+" "+path);var prefab=DataLoader.LoadAsset<GameObject>(path,true);foreach(var f in prefab.GetComponentsInChildren<MeshFilter>(true))s.AppendLine("BOUNDS "+f.name+" "+f.sharedMesh.bounds.ToString("F5"));foreach(var t in prefab.GetComponentsInChildren<Transform>(true))s.AppendLine("NODE "+t.name+" p="+t.localPosition.ToString("F5")+" r="+t.localEulerAngles.ToString("F3")+" scale="+t.localScale.ToString("F3"));}
  var custom=DataLoader.LoadAsset<GameObject>("#@modfolder(ZDelvePresentation):Resources/forestweapons.unity3d?delveBoneDagger",true);foreach(var t in custom.GetComponentsInChildren<Transform>(true))s.AppendLine("CUSTOM "+t.name+" p="+t.localPosition+" r="+t.localEulerAngles+" scale="+t.localScale);foreach(var skin in custom.GetComponentsInChildren<SkinnedMeshRenderer>(true))s.AppendLine("CUSTOMBOUNDS "+skin.sharedMesh.bounds.ToString("F5"));File.WriteAllText(Path.Combine(GameIO.GetUserGameDataDir(),"batch02-diagnosis.txt"),s.ToString());return s.ToString();
 }
